(self.webpackChunkjalaranu_web=self.webpackChunkjalaranu_web||[]).push([[125],{1396:function(a){a.exports={siteMetadata:{siteUrl:"https://jalaranu.org",title:"Jalaranu"},pathPrefix:{}.PATH_PREFIX||"",plugins:[{resolve:"gatsby-plugin-manifest",options:{name:"Jalaranu",short_name:"Jalaranu",start_url:"/en/",background_color:"#101820",theme_color:"#101820",display:"standalone",lang:"en",description:"The world's first underlake datacenter project.",icon:"static/assets/icon-512.png",icon_options:{purpose:"any maskable"},include_favicon:!1}},{resolve:"gatsby-plugin-offline",options:{precachePages:["/en/","/id/"]}}]}},5070:function(a,e,n){"use strict";n.r(e),n.d(e,{Head:function(){return m},default:function(){return c}});var i=n(6540),t=n(6658),s=JSON.parse('{"locale":"en","langLabel":"EN","default":true,"site":{"title":"Jalaranu","tagline":"Underlake datacenter project","description":"Explore the world\'s first underlake datacenter project: Jalaranu\'s validation approach and partnership opportunities for computing infrastructure in Indonesia.","footerTagline":"Jalaranu - developing an underlake datacenter project to support Indonesia\'s digital resilience. The project evaluates thermal efficiency, operational reliability, and environmental effects through a staged, evidence-led program before any commitment to construction.","copyright":"Jalaranu","logoAlt":"Jalaranu","ogImageAlt":"Jalaranu wordmark on a dark background with the headline Computing infrastructure beneath the lake.","skipLink":"Skip to main content","menuToggle":"Toggle menu","socialFollow":"Follow Jalaranu","social":{"instagram":"https://instagram.com/projectjalaranu","x":"https://x.com/projectjalaranu","linkedin":"https://linkedin.com/company/jalaranu","facebook":"https://www.facebook.com/jalaranu","tiktok":"https://www.tiktok.com/@jalaranu","github":"https://github.com/jalaranu"},"languageSwitch":"Switch language to","languageMenu":"Language","languages":{"en":"English","id":"Bahasa Indonesia"},"carouselPrev":"Previous slide","carouselNext":"Next slide","carouselPause":"Pause slideshow","carouselPlay":"Play slideshow","carouselGoTo":"Go to slide","carouselSlides":"Hero image slides","brandSlogan":"Cold, silent, a sustainable data realm. The world\'s first underlake datacenter project."},"nav":{"technology":"Technology","useCases":"Use Cases","validation":"Milestones","partnerships":"Partnerships","about":"About","primaryCta":"Discuss a Partnership"},"pages":{"home":{"seoTitle":"Jalaranu | Underlake Datacenter Project","seoDescription":"Explore the world\'s first underlake datacenter project: Jalaranu\'s validation approach and partnership opportunities for computing infrastructure in Indonesia.","hero":{"eyebrow":"Underlake datacenter project","h1":"Computing infrastructure **beneath the lake**. Supporting Indonesia\'s ==digital resilience==.","intro":["Jalaranu is developing the world\'s first eco-friendly modular underlake datacenter to evaluate thermal efficiency, operational reliability, and deployment feasibility in Indonesia.","We welcome collaboration with investors, institutions, and technology partners to establish a measurable foundation for development."],"primaryCta":{"label":"Discuss a Partnership","to":"/en/partnerships/#contact"},"secondaryCta":{"label":"Explore the Technology","to":"/en/technology/"},"caption":"Project illustration. Final configuration is subject to study and engineering findings.","imageAlt":"Project illustration: the Jalaranu datacenter module beneath the lake surface, connected to shore-based support facilities by protected power and communication routes.","slides":[{"src":"/assets/hero/danau-batur.webp","alt":"Lake Batur, Bali, seen from its volcanic shore"},{"src":"/assets/hero/danau-matano.webp","alt":"Lake Matano, South Sulawesi, an ancient deep-water lake"}]},"why":{"h2":"Why consider a location **beneath a lake**?","body":["Underwater placement offers a different approach to heat management, physical space, and infrastructure access. Its potential benefits need to be assessed alongside the implications for deployment, maintenance, connectivity, and recovery.","The central question is: under what conditions would this approach be more feasible than a land-based datacenter using water-based cooling?","Jalaranu places that comparison at the centre of its evaluation."],"focuses":[{"title":"Thermal performance","body":"**Assessing heat transfer** and energy demand under defined site conditions and workloads."},{"title":"Operational reliability","body":"**Testing how the system can be monitored, maintained, and recovered** when disruptions occur."},{"title":"Overall feasibility","body":"**Comparing whole-life costs** and responsibilities towards the environment."}],"cta":{"label":"See the Milestones","to":"/en/milestones/"}},"system":{"h2":"One system, from shore to submerged module.","body":"The Jalaranu project connects shore-based support facilities with a computing module beneath the water. Planning covers power, connectivity, heat management, monitoring, and how the module is deployed and retrieved.","items":[{"title":"Shore facilities","body":"Interfaces for power, networking, and operational management."},{"title":"Shore-to-module connections","body":"Power and communications routes to be designed around service-continuity requirements."},{"title":"Underwater module","body":"A computing enclosure and supporting systems to be evaluated through engineering and testing."},{"title":"Monitoring and recovery","body":"Observation of system conditions, incident response, and module retrieval."}],"cta":{"label":"Understand the Project","to":"/en/technology/#system"}},"validation":{"h2":"Progress assessed through evidence.","body":["Each development stage needs to answer specific questions: does performance meet the requirement, how does the system behave when it fails, what does it cost to operate, and how are environmental effects assessed?","Test plans, measured results, and their limitations provide the basis for decisions about further development."],"cta":{"label":"Explore Milestones","to":"/en/milestones/"}},"partnerships":{"h2":"Help shape Jalaranu\'s next stage.","tracks":[{"title":"Investors","body":"Explore milestone-based funding and business-model evaluation."},{"title":"Government and defence","body":"Discuss use requirements, evaluation criteria, and potential pilot development."},{"title":"Industry partners","body":"Explore contributions to engineering, energy, networks, manufacturing, and operations."},{"title":"Research partners","body":"Develop test methods and technical, economic, and environmental studies."}],"cta":{"label":"Find Your Partnership Route","to":"/en/partnerships/"}},"closing":{"h2":"What would need to be ==demonstrated for this project to be relevant== to your organisation?","body":"Start with your requirements, the scope of evaluation, and the contribution we could develop together.","cta":{"label":"Discuss a Partnership","to":"/en/partnerships/#contact"}}},"technology":{"seoTitle":"Underlake Datacenter Technology | Jalaranu","seoDescription":"Explore the world\'s first underlake datacenter project: from shore facilities and computing modules to heat management, connectivity, and recovery.","hero":{"h1":"Engineering starts with the right questions.","body":"Jalaranu explores the underlake datacenter as **one complete system**. Module placement needs to be evaluated together with power, networking, heat management, maintenance, and recovery."},"architecture":{"h2":"From shore interfaces to the underwater environment.","body":["The project architecture includes four elements: shore-based support facilities, power and communications connections, the computing module, and monitoring and operational management. Their relationships determine how the overall facility can function and recover.","Early visualisations use a truncated square pyramid. This is a design exploration; final geometry, materials, and specifications will follow engineering and test findings."],"anchor":"system","visualNote":"A block diagram and cross-section showing logical connections, without coordinates or facility-security details.","imageAlt":"Engineering figure of the truncated-pyramid module: front elevation, section A-A, roof framing plan, and watertight joint detail.","imageCaption":"Dimensional engineering draft, not a fabrication drawing."},"engineering":{"h2":"Five areas to evaluate.","items":[{"title":"Heat management","body":"**Water conditions, heat transfer**, computing loads, and the energy required by supporting systems."},{"title":"Module integrity","body":"**The ability of structures, joints, and system interfaces** to withstand the defined operating conditions."},{"title":"Power and connectivity","body":"**Service needs, redundancy options**, behaviour during connection failures, and recovery procedures."},{"title":"Maintenance","body":"**What can be monitored remotely**, when intervention is required, and how the module can be handled or retrieved."},{"title":"Security and control","body":"**Administrative access, event monitoring, key management**, operator responsibilities, and protection of physical and digital interfaces."}]},"comparison":{"h2":"Advantages need to be assessed against relevant alternatives.","body":["Evaluation should compare the underlake project with land-based solutions using equivalent service requirements, workloads, and assumptions. Relevant comparisons include land-based facilities with conventional cooling and water-based cooling, where applicable to the site under study.","Assessment covers energy, capital expenditure, operating costs, maintenance, connectivity, recovery, environmental effects, and end of life. Potential savings in one component do not in themselves demonstrate a lower total cost."]},"placements":{"h2":"Placement alternatives, compared honestly.","intro":["The underlake project is evaluated against three reference placements at equal service: a terrestrial facility, a hardened bunker, and an undersea deployment. Each trade-off below is an initial assessment to be tested, not a measured result.","A companion ten-year cost model at equal service gives 6.00 million dollars for a terrestrial facility with conventional cooling, 6.34 for a hardened terrestrial facility with lake-water cooling, and 7.85 for the submerged design. Submersion buys capability, not cost saving."],"note":"Initial framework assessment for discussion. Figures and rankings require measurement and site studies. Screening thermal numbers (a basin-average anomaly of about 0.001 kelvin over fifty years and a twelve-month footprint of 228-509 metres) carry unproven status until measured.","table":{"rowHeading":"Criterion","columns":[{"icon":"droplets","name":"Underlake datacenter","sub":"Freshwater lake"},{"icon":"waves","name":"Undersea datacenter","sub":"Ocean deployment"},{"icon":"building2","name":"Terrestrial datacenter","sub":"Conventional cooling"},{"icon":"shield-check","name":"Hardened bunker","sub":"Reinforced shell"}],"rows":[{"icon":"history","label":"Operational maturity","values":["Prototype and testing in progress","Proven at sea (Project Natick)","Proven operations","Proven for critical workloads"]},{"icon":"shield","label":"Physical protection","values":["Pressure hull, inland water column","Hardened shell, remote siting","Site security, exposed perimeter","Reinforced construction, restricted access"]},{"icon":"thermometer","label":"Heat rejection","values":["Passive water cooling, thermal budget unmeasured","Passive water cooling","Mechanical cooling, energy cost","Complex confined heat rejection"]},{"icon":"scale","label":"Jurisdiction","values":["Domestic inland waters","Contested maritime zones","Domestic, urban corridors","Domestic"]},{"icon":"landmark","label":"Land threat surface","values":["Submerged module, shore station remains exposed","Remote at sea, shore station remains exposed","Direct perimeter access, site security required","Reinforced against intrusion, restricted access"]},{"icon":"plane","label":"Air threat surface","values":["Module shielded by the water column, shore station exposed","Exposed surface support at sea","Fully exposed from the air","Hardened against aerial threats"]},{"icon":"anchor","label":"Maritime threat surface","values":[{"text":"Out of submarine reach","highlight":true},"Submarine cable interception, anchor drag","None","None"]},{"icon":"boxes","label":"Scalability","values":["Lake-limited modules","Site-limited modules","Hyperscale clusters","Harder to scale"]},{"icon":"dollar-sign","label":"Ten-year cost model","values":["$7.85M","Not modeled","$6.00M","$6.34M"]},{"icon":"flask-conical","label":"Evidence status","values":["Computed","Proven pilot","Measured","Measured"]}]}},"scenarios":{"h2":"Use cases under exploration","body":["The project can be evaluated for dedicated computing, storage, or particular infrastructure requirements defined by an organisation. The suitability of each use case must be established through requirements assessment and test evidence.","A use case mentioned here is not a statement that the service is already available or approved to handle sensitive data."],"cta":{"label":"Discuss Technical Requirements","to":"/en/partnerships/#contact"}},"indexLabel":"On this page","indexMoreLabel":"More sections","index":[{"id":"system","label":"Project architecture"},{"id":"inside","label":"Inside Jalaranu"},{"id":"comparison","label":"Comparing alternatives"},{"id":"placements","label":"Placement comparison"},{"id":"scenarios","label":"Use cases under exploration"}],"inside":{"h2":"Inside Jalaranu","anchor":"inside","intro":["The reference structure breaks the module into 24 numbered components across six systems. The figure is a dimensional engineering draft, not a fabrication drawing."],"items":[{"title":"Protective enclosure","body":"Stainless-steel shell, structural stiffeners, and corrosion protection, carried by a ballast skid. Lifting loads pass through four upper padeyes, while the service lid keeps two seals separated by a monitored interspace."},{"title":"Computing cassette","body":"An 8U cassette holds three 2U servers with SSD/NVMe storage and a network switch, under a proposed nitrogen atmosphere with controlled humidity and A/B power and fibre feedthroughs."},{"title":"Cooling loop","body":"A gas-to-liquid coil and fans move heat into a closed coolant circuit through A/B pumps and A/B external heat exchangers. Isolation valves separate branches, and lake water never mixes with internal coolant."},{"title":"Power resilience","body":"An optional LiFePO4 battery UPS sits in a lower bay separated from the computing equipment, targeting a ten-minute reserve at the assumed 2.1 kW load."},{"title":"Vibration isolation","body":"Four captive isolators with cushioned snubbers suspend the server cassette, with flexible connections, electrical bonding, and transport and service locks."},{"title":"Monitoring and safety","body":"Temperature, humidity, oxygen, pressure, and motion sensors, a camera with window and wiper, and a leak-detection tray feed power distribution and safety controls."}],"note":"All stated values are design assumptions, not measurements. Watertightness, operating depth, lifting capacity, and seismic resistance remain to be established through analysis and integrated testing."}},"useCases":{"seoTitle":"Use Cases: Strategic Data & Critical Services | Jalaranu","seoDescription":"Explore Jalaranu use cases for classified information, service recovery, base support, strategic analytics, computing, and essential archives.","indexLabel":"On this page","indexMoreLabel":"More sections","index":[{"id":"data","label":"Data to protect"},{"id":"use-cases","label":"Use cases"},{"id":"mapping","label":"Sector mapping"},{"id":"needs","label":"Cross-sector needs"},{"id":"approach","label":"Evaluation approach"}],"hero":{"eyebrow":"Use Cases · Strategic data and critical services","h1":"For data that must remain protected. For services that must ==keep running==.","intro":["From strategic state information to financial services and vital infrastructure, every sector has different requirements for protecting the confidentiality, integrity, and availability of data.","Jalaranu is developing an underlake datacenter concept to explore approaches to physical protection, infrastructure placement, and service continuity for these needs.","Find the use case that fits your requirements and discuss what we need to validate together."],"primaryCta":{"label":"Discuss Your Infrastructure Requirements","to":"/en/partnerships/#contact"},"secondaryCta":{"label":"Explore the Milestones Approach","to":"/en/milestones/"}},"data":{"h2":"The value of information shapes its protection requirements.","intro":["Classified information requires controls over access and disclosure. Critical data requires integrity and availability to support essential functions. A dataset can have both characteristics."],"illustrationAlt":"Concept illustration of the Jalaranu datacenter beneath a lake, connected to shore-based support facilities.","illustrationCaption":"Concept illustration. Final configuration is subject to study and engineering findings.","tableHeaderRequirement":"Requirement","tableHeaderFocus":"Protection focus","tableHeaderApplications":"Potential applications","rows":[{"icon":"lock","requirement":"**Classified information and state secrets**","focus":"Confidentiality, restricted access, management control, and handling under appropriate authority.","applications":"Defence documents, intelligence information, diplomatic archives, and strategic documents formally designated as classified."},{"icon":"database","requirement":"**Critical data and services**","focus":"Integrity, availability, and the ability to recover when disruption occurs.","applications":"Transaction data, public-service applications, and information systems supporting energy and transport."},{"icon":"layers","requirement":"**Strategic information assets**","focus":"Protection against loss, unauthorised modification, and unauthorised access.","applications":"Exploration data, industrial designs, research findings, intellectual property, and essential state archives."}]},"explore":{"h2":"Start with the functions you need to protect and support.","intro":["The same requirement can arise across several sectors. These eight use cases provide a starting point for identifying the data, services, and requirements to evaluate with Jalaranu."],"cardsLabel":"Select a use case to jump to its description.","sectorsLabel":"Relevant sectors","applicationsLabel":"Potential applications","objectiveLabel":"Objective","validateLabel":"To validate","cards":[{"id":"classified","icon":"lock","title":"Classified Information & State Secrets","sectors":["Defence","Intelligence","Government"],"body":"Storage and processing environments for information whose disclosure or modification could affect strategic state interests.","applications":["Defence documents, intelligence information, and diplomatic archives under appropriate classification and authority.","Strategic policy documents formally designated as classified.","Segregated processing environments, access controls, and audit trails.","Recovery copies of sensitive information with institution-defined access and key management."],"objective":"Preserve confidentiality, integrity, and institutional control over information.","toValidate":"Classification requirements, personnel authorisation, key management, system segregation, and physical and digital security."},{"id":"recovery","icon":"life-buoy","title":"Disaster & Cyber Recovery","sectors":["Finance","Government","Healthcare","Telecoms","Energy","Transport","Defence"],"body":"Recovery capacity for data and applications when primary services are disrupted by physical incidents, facility failures, or cyber incidents.","applications":["Additional copies of transaction data, administrative records, health records, and operational support data.","Recovery environments with access and dependencies separated from primary systems.","Restoration of public-service applications, hospital systems, and operator services.","Periodic data and application recovery testing, including data integrity checks."],"objective":"Restore priority functions within acceptable recovery time and data-loss objectives.","toValidate":"Recovery objectives, differing risk exposures, power and network dependencies, backup isolation, and recovery test results. Replication alone does not ensure recovery from a cyber incident."},{"id":"base-support","icon":"radio","title":"Base Support & Defence Readiness","sectors":["Military & defence"],"body":"Computing, storage, and supporting applications for permanent bases and **Forward Operating Bases (FOBs)**, subject to deployment and connectivity requirements.","applications":["Digital services supporting FOBs and permanent bases.","Infrastructure for command information and coordination systems.","Logistics, inventory, maintenance, and asset-readiness management.","Simulation, training, research, and test environments.","Storage and recovery of base-support data."],"objective":"Support information availability and continuity of services underpinning defence readiness.","toValidate":"Local service requirements, data classification, operational control, communications dependencies, and maintenance and recovery procedures."},{"id":"analytics","icon":"radar","title":"Strategic Analytics & Geospatial Processing","sectors":["Intelligence","Defence","Government","Energy","Maritime","Logistics"],"body":"Processing environments that turn large datasets into information supporting analysis and decision-making.","applications":["Processing and storage of imagery, geospatial data, and intelligence, surveillance, and reconnaissance (ISR) data under appropriate authority.","Analysis of open sources and other lawfully obtained information.","Risk analysis covering the economy, energy, supply chains, and infrastructure.","Processing of maritime environmental information and logistics planning data.","Analytical workspaces with segregated access and audit trails."],"objective":"Provide processing capacity and data governance for strategic analysis.","toValidate":"Data provenance and authority to use it, computing requirements, latency, integrity, and workspace segregation."},{"id":"research","icon":"cpu","title":"Research Computing, Modelling & Simulation","sectors":["Energy","Finance","Healthcare","Defence","Universities","Research institutions"],"body":"Computing capacity for analytical and scientific workloads requiring intensive data processing.","applications":["Seismic-data processing, reservoir modelling, and simulation of energy systems and industrial processes.","Risk modelling, stress testing, actuarial computing, and fraud analytics.","Processing of genomic data, medical images, and research datasets under appropriate authority.","Engineering simulation, defence research, and test environments.","Shared research infrastructure with universities and laboratories."],"objective":"Support data processing and experimentation with capacity matched to workload requirements.","toValidate":"Workload profiles, computing hardware, power, heat rejection, data transfer, maintenance requirements, and whole-life facility costs."},{"id":"regional","icon":"server","title":"Regional Computing & Digital Services","sectors":["Telecoms","Digital infrastructure operators","Government","Regional service partners"],"body":"Placement of computing and storage capacity to serve users and applications within a region.","applications":["Regional application hosting and storage.","Network-management applications, service monitoring, and operator analytics.","Content caching where demand patterns and connectivity support it.","Dedicated computing infrastructure for partner requirements.","Additional capacity and replicas for digital services."],"objective":"Provide capacity in locations suited to demand and network architecture.","toValidate":"Actual connectivity, latency, network capacity, alternative routes, user requirements, and site economics."},{"id":"operations","icon":"clipboard-list","title":"Operational Support & Asset Management","sectors":["Energy","Transport","Maritime","Logistics","Defence"],"body":"Information infrastructure for planning, monitoring, and maintaining assets and operational support services.","applications":["Analysis of operational histories and predictive maintenance.","Information applications supporting ports, distribution, and supply chains.","Fleet, inventory, capacity, and asset-readiness management.","Storage of facility designs and technical documentation.","Replication and recovery of applications supporting operations."],"objective":"Preserve access to information needed for asset management and continuity of activities.","toValidate":"System integration, data quality, connectivity, and separation from real-time or safety-control functions."},{"id":"archives","icon":"archive","title":"Strategic Archives & Intellectual Property Protection","sectors":["Government","Energy","Finance","Healthcare","Industry","Research institutions"],"body":"Managed storage for information that must remain intact, traceable, and accessible to authorised users throughout its retention period.","applications":["Essential state archives, land records, and administrative data.","Exploration, geological, and resource-reserve data, and industrial designs.","Audit archives and transaction evidence with integrity controls.","Research findings, medical data, and intellectual property under their respective governance requirements.","Integrity checks, retrieval testing, and migration of media or formats."],"objective":"Preserve the long-term value of information and support traceability and reuse.","toValidate":"Retention policies, access rights, capacity, retrieval times, integrity, and technology migration plans."}]},"mapping":{"h2":"Sector and use-case mapping","intro":["One requirement can appear across sectors. The mapping below connects example requirements to the related use cases."],"tableHeaderSector":"Sector","tableHeaderRequirements":"Example requirements","tableHeaderUseCases":"Related use cases","rows":[{"sector":"Defence & military","requirements":"Classified information, FOB and base support, asset readiness","useCases":[1,2,3,4,5,7]},{"sector":"Intelligence & national security","requirements":"Sensitive information and strategic analysis","useCases":[1,2,4]},{"sector":"Government","requirements":"State secrets, public services, state archives","useCases":[1,2,4,6,8]},{"sector":"Energy & natural resources","requirements":"Exploration data, simulation, asset operations","useCases":[2,4,5,7,8]},{"sector":"Banking & financial services","requirements":"Service recovery, risk computing, transaction evidence","useCases":[2,5,8]},{"sector":"Telecomm & digital infrastructure","requirements":"Regional capacity and service continuity","useCases":[2,6]},{"sector":"Transport, maritime & logistics","requirements":"Operational information, geospatial data, asset management","useCases":[2,4,7]},{"sector":"Healthcare & strategic research","requirements":"Sensitive data, system recovery, scientific computing","useCases":[2,5,8]}]},"needs":{"h2":"Four needs that connect every sector.","items":[{"icon":"key-round","title":"Protecting sensitive information","body":"Define who is authorised to access, manage, and process data. Protection requirements need to reflect information classification and institutional responsibilities."},{"icon":"shield","title":"Resilience to physical disruption","body":"Evaluate how the location, placement, and design of a facility affect its risk exposure. Module protection needs to be considered together with power, connectivity, supporting facilities, and recovery."},{"icon":"rotate-ccw","title":"Continuity and recovery","body":"Establish which data and services must be preserved, how recovery will work, and how its success will be tested when a facility or region is disrupted."},{"icon":"user-cog","title":"Operational control","body":"Clarify who operates the system, manages access and keys, oversees suppliers, and is accountable for the service."}]},"approach":{"h2":"Start with requirements. Proceed through evidence.","body":["The suitability of underlake deployment needs to be assessed against organisational requirements, site conditions, and relevant alternatives."],"flowLabel":"Evaluation path","flowCaption":"Conceptual overview of the evaluation path. Suitability is established through evidence, not assumed.","flow":[{"icon":"search","title":"Requirements assessment","body":"Data, services, impact, and control requirements to support."},{"icon":"flask-conical","title":"Technical validation","body":"Testing of technical, economic, and environmental feasibility."},{"icon":"key-round","title":"Institutional fulfilment","body":"Access, classification, and governance requirements of the relevant institution."},{"icon":"scale","title":"Suitability determination","body":"An evidence-based decision on fit and next steps."}],"discussionIntro":"Initial discussions cover:","discussion":["The types of data and service functions to be supported.","The consequences of data disclosure, modification, loss, or unavailability.","Requirements for access, management, and operational control.","Recovery objectives and dependencies on power and networks.","The testing needed to assess technical, economic, and environmental feasibility."],"scopeTitle":"Scope","scope":"Suitability for classified information and critical services is determined through requirements assessment, technical validation, and fulfilment of the relevant institution\'s requirements.","cta":{"label":"Explore the Milestones Approach","to":"/en/milestones/"}},"closing":{"h2":"What information must remain ==protected== when conditions change?","body":"Start with your organisation\'s needs: the data to safeguard, the services to recover, and the requirements to meet.","helperText":"Share general context first. Do not submit classified information, credentials, or restricted documents through the public form.","cta":{"label":"Discuss Your Infrastructure Requirements","to":"/en/partnerships/#contact"}}},"validation":{"seoTitle":"Development Milestones | Jalaranu","seoDescription":"Learn how the world\'s first underlake datacenter project is validated: test questions and a staged approach to evaluating feasibility.","hero":{"h1":"Evidence provides the basis for the next step.","body":"The feasibility of an underlake datacenter needs to be assessed **technically, economically, and environmentally**. Jalaranu\'s validation approach focuses on testable questions, explainable methods, and findings presented alongside their limitations."},"status":{"h2":"Development status","items":["Jalaranu is now in the prototype and testing stage. The current stage is announced here and will be kept up to date.","Test questions, methods, and any evidence approved for sharing will be published as they become available."]},"plan":{"h2":"Questions that shape the test programme.","body":"Success criteria, methods, and responsibilities are defined ahead of each test step, so every result can be judged against published criteria.","table":[{"area":"Thermal performance and energy","question":"How does the system perform across defined workloads and environmental conditions?"},{"area":"Structure and integrity","question":"Do the module and its interfaces meet the specified operating and test conditions?"},{"area":"Reliability and recovery","question":"How does the system respond to disruptions, recover, and undergo maintenance?"},{"area":"Whole-life cost","question":"How do installation, operation, intervention, retrieval, and end-of-life costs compare with alternatives?"},{"area":"Environment","question":"How is the baseline documented, change monitored, and the evidence evaluated?"},{"area":"Fitness for use","question":"For which requirements and service levels do test results indicate suitability?"}],"tableHeaderArea":"Area","tableHeaderQuestion":"Evaluation question"},"framework":{"h2":"Staged development, with decisions at each stage.","steps":[{"title":"Requirements definition","body":"Establish objectives, relevant alternatives, and success criteria."},{"title":"Studies and preliminary engineering","body":"Assess candidate sites for further study, risks, system design, and cost assumptions."},{"title":"Component and integration testing","body":"Test the functions that determine system safety and performance."},{"title":"A limited pilot","body":"Measure performance within an agreed scope, supported by monitoring and recovery plans."},{"title":"Evaluation for the next stage","body":"Review findings, limitations, and the feasibility of further development."}],"note":"This sequence is a development framework, not a list of stages claimed to be complete."},"environment":{"h2":"Environmental commitments","body":["Site studies need to consider water conditions, uses of the area, the needs of affected communities, and applicable requirements. The evaluation plan should cover baseline conditions, changes to monitor during testing, and the handling of facilities at end of life.","Study findings inform site and design decisions, including a decision not to proceed with an option if it is unsuitable."],"items":[{"title":"Ecological discipline","body":"The lake is the limiting resource; environmental benefit is never claimed without measurement."},{"title":"A published thermal budget","body":"Screening calculations give a basin-average anomaly of about 0.001 kelvin over fifty years and a twelve-month heat-equivalent footprint of 228-509 metres. Both stay unproven until measured at a candidate site."},{"title":"Baseline before deployment","body":"Baseline conditions, water conditions, area uses, and the needs of affected communities are part of the evaluation plan."},{"title":"End of life","body":"Decommissioning, retrieval, and lake restoration are planned from the start."},{"title":"No-proceed stays valid","body":"Where evidence is insufficient, an option is set aside rather than asserted."}]},"results":{"h2":"Findings and documents","body":"Published findings and documents will appear here once they are available and approved for public release.","cta":{"label":"Discuss the Programme","to":"/en/partnerships/#contact"}},"faq":[{"q":"Is Jalaranu commercially operational?","a":"**This website introduces the Jalaranu project and development opportunities.** Commercial service availability will be communicated separately once facility and service readiness have been confirmed."},{"q":"Why use a lake?","a":"**A lake is the deployment context being explored.** Suitability needs to be assessed against water conditions, access, energy, networking, environmental factors, and intended use. Selecting a lake does not in itself demonstrate an advantage over another location or design."},{"q":"Is the cooling free or energy-free?","a":"**The potential use of the water environment must be assessed alongside heat-transfer systems and the energy requirements of the whole facility.** Jalaranu does not claim specific savings without measured results and a clearly defined comparison."},{"q":"What happens if the module needs repair?","a":"**Monitoring, incident handling, retrieval, and component replacement are part of design evaluation.** Detailed procedures will follow the tested design and agreed service requirements."},{"q":"Can it support sensitive data or defence requirements?","a":"**Suitability needs to be assessed against data classification, system architecture, access controls, governance, and the requirements of the relevant institution.** This website does not claim approval or readiness to handle information at a particular classification level."},{"q":"How are effects on the lake assessed?","a":"**The study approach covers baseline conditions, changes to monitor, and evaluation during testing and at end of life.** Its scope must be adapted to the location and planned activities."},{"q":"How can I obtain more information?","a":"**Use the partnership form to introduce your organisation and the purpose of the discussion.** Information that can be shared will depend on the needs of the discussion and document availability."}],"faqTitle":"Frequently asked questions"},"partnerships":{"seoTitle":"Datacenter Development Partnerships | Jalaranu","seoDescription":"Explore collaboration with Jalaranu as an investor, government or defence institution, industry partner, or research organisation.","hero":{"h1":"Start with the requirement. Agree on what needs to be demonstrated.","body":"Jalaranu welcomes conversations with organisations interested in evaluating, developing, or supporting the underlake datacenter project. Collaboration begins with **clear goals, realistic scope, and measurable results**."},"tracks":[{"id":"investor","h2":"Funding linked to measurable progress.","body":["We invite discussion of market needs, the business model, funding stages, and the evidence required at each stage. The initial focus is to understand how capital can reduce development uncertainty.","Topics include prospective users, available alternatives, cost estimates and their assumptions, capital requirements, and milestones for subsequent investment decisions."],"cta":{"label":"Discuss an Investment Opportunity","formPreset":"investor"}},{"id":"institution","h2":"Evaluate strategic requirements through focused collaboration.","body":["Discussion can begin with infrastructure needs, service continuity, operational control, data governance, and institutional evaluation criteria. The suitability of the Jalaranu project is determined through requirements assessment and relevant testing.","Potential collaboration may include feasibility studies, requirements definition, and the development of a limited pilot. Access requirements, information handling, and each party\'s responsibilities are agreed according to the scope of collaboration."],"cta":{"label":"Explore Institutional Collaboration","formPreset":"institution"}},{"id":"industry","h2":"Connecting engineering, infrastructure, and operational capabilities.","body":["We welcome discussions with prospective partners in energy, connectivity, structures and manufacturing, computing, heat management, sensors, and field operations.","Contributions can be defined around development requirements, interface boundaries, integration responsibilities, and the test outcomes the parties aim to achieve together."],"cta":{"label":"Discuss a Technology Contribution","formPreset":"industry"}},{"id":"research","h2":"Developing methods and evidence that can be reviewed.","body":["Universities and research organisations can explore thermal, structural, reliability, economic, and environmental studies. Research scope, data use, publication, and rights to outcomes need to be agreed from the outset."],"cta":{"label":"Explore Research Collaboration","formPreset":"research"}}],"process":{"h2":"From an initial conversation to a shared scope of work.","steps":["Describe your organisation\'s requirements and objectives.","Discuss fit and the initial information that can be shared.","Define scope, contributions, and evaluation criteria.","Determine the next step based on both parties\' readiness."]},"contact":{"h2":"Tell us what your organisation needs.","body":"Provide brief context and the type of collaboration you would like to explore. Do not include confidential information, credentials, sensitive operational data, or restricted documents in this form.","privacyLink":"Read how your contact information is handled in our Privacy Notice.","helpText":"Sensitive technical details are not needed at this stage.","fields":{"name":"Full name","org":"Organisation name","email":"Contact email","type":"Partnership type","selectPlaceholder":"Select collaboration type","typeOptions":["Investor","Government or defence institution","Industry or technology partner","Research partner","Other"],"message":"Requirements and collaboration objectives","messagePlaceholder":"Describe your requirements, a contribution you could offer, or your initial questions.","submit":"Send Discussion Request"},"success":"Thank you. Your discussion request has been received. The Jalaranu team will review the information you submitted.","error":"Your request has not been sent. Please try again.","unavailable":"The discussion form is not yet active. No data is transmitted from this page. The contact channel will be announced once established.","requiredError":"Please complete this field.","emailError":"Enter a valid email address.","captchaError":"Please complete the security check before sending."}},"about":{"seoTitle":"About Jalaranu | Identity and Development","seoDescription":"Discover the story behind the world\'s first underlake datacenter project: Jalaranu\'s identity, development principles, and the people responsible.","hero":{"h1":"Rooted in Indonesian identity. Developed through evidence.","body":"Jalaranu is developing an underlake datacenter and treats Indonesia\'s lakes as strategic national assets that must be understood before they are used. We turn that ambition into a **measurable process**: questions and methods are published up front, and findings are shared with their evidence and limits as they are approved for release. The project advances in stages, and we state plainly what is proven, what is not yet proven, and what we still do not know."},"story":{"h2":"Knowledge, safeguarded.","body":["The name Jalaranu combines “jala”, understood as water in the naming of this brand, and “ranu”, lake. Its visual identity draws inspiration from Javanese heritage.","A guardian goddess supports a datacenter beneath flowing water. The symbol expresses a responsibility to safeguard knowledge and the infrastructure that supports it.","That meaning carries into the way the project is developed: clear questions, focused testing, and honest communication about findings and limitations."]},"principles":{"h2":"Development principles","items":[{"title":"Evidence before scale","body":"Development decisions follow evaluation findings."},{"title":"Responsibility across the facility\'s life","body":"Planning covers installation, operation, recovery, and end of life."},{"title":"Collaboration with clear roles","body":"Contributions, interfaces, and responsibilities are agreed from the outset."},{"title":"Proportionate openness","body":"Public information explains the project rationale; detailed discussion follows need and access authority."}]},"team":{"h2":"Team and organisation","body":"Jalaranu is built by dedicated people who believe Indonesian infrastructure should be built on measured evidence, not assumptions: engineers, security practitioners, and strategists who publish the project\'s questions and methods, and share findings that are approved for release. The work is organised across three partners with complementary roles: COCONUT Computer Club leads the engineering, PERKAMINDO is responsible for information security, and PT Lontar Riset Indonesia for strategy and business. Collaboration remains open to other parties who share the project\'s standards.","items":[{"name":"COCONUT Computer Club","role":"Engineering","url":"https://coconut.or.id","logo":"/assets/partners/coconut-logo-blue.svg"},{"name":"PERKAMINDO","role":"Information security","url":"https://perkamindo.org","logo":"/assets/partners/perkamindo-horizontal.svg"},{"name":"PT Lontar Riset Indonesia","role":"Strategy and business","url":"https://lontartech.co.id","logo":"/assets/partners/lontar-logo.svg"}],"cta":{"label":"Open for collaboration","to":"/en/partnerships/"}},"paper":{"h2":"Published research","body":"The engineering reasoning, threat model, thermal screening, and cost comparison behind this project are documented in an open paper. Read it directly or save a copy.","linkLabel":"Paper - An Underlake Data Center Framework for Intelligence Infrastructure and Indonesian National Resilience","linkHref":"/assets/jalaranu-underlake-datacenter-paper.pdf","cite":"[PDF 1]"}},"privacy":{"seoTitle":"Privacy | Jalaranu","seoDescription":"The Jalaranu Privacy Notice will explain how contact-form information is handled once the practices are established.","h1":"Privacy Notice","body":["This Privacy Notice will be updated before the contact form is launched. It will explain the operator, the purposes of processing, service providers, retention, and the channel for your data-related requests once the actual practices are established."],"sections":[{"title":"Scope of this notice","body":["This page explains how contact information would be handled once the Jalaranu contact form and related processes are active. The current website is static and does not collect personal data by itself."]},{"title":"Information we plan to collect","body":["When the partnership form becomes active, the information requested will be limited to what is needed to review an enquiry: full name, organisation name, contact email, type of collaboration, and a message describing the organisation\'s needs."]},{"title":"How the information would be used","body":["The information would be used solely to review and respond to partnership enquiries, and to prepare follow-up discussions. It would not be used for marketing without consent and would not be sold to third parties."]},{"title":"Storage, retention and access","body":["Storage location, retention period, access controls, and the responsible data controller will be published here once the form and its processing practices are established. Until then, no form data is processed."]},{"title":"Your rights and contact","body":["Once processing begins, you will be able to request information about your data, corrections, or deletion through the contact channel published on this page. Use the partnership page contact form to reach the team about this notice."]}]},"notFound":{"h1":"Page not found","body":"The page you are looking for does not exist or has moved.","back":"Back to Home","seoTitle":"Page Not Found | Jalaranu","seoDescription":"The page you are looking for could not be found. Return to the Jalaranu website."}},"footer":{"privacy":"Privacy","contact":"Contact","privacyNote":"The Privacy Notice will be updated to reflect actual data-handling practices.","legalHeading":"Legal","email":"info@jalaranu.org"},"slugs":{"technology":"technology","useCases":"use-cases","validation":"milestones","partnerships":"partnerships","about":"about","privacy":"privacy"}}'),r=JSON.parse('{"locale":"id","langLabel":"ID","default":false,"site":{"title":"Jalaranu","tagline":"Proyek datacenter bawah danau","description":"Jelajahi proyek datacenter bawah danau pertama di dunia: pendekatan validasi Jalaranu dan peluang kemitraan untuk infrastruktur komputasi di Indonesia.","footerTagline":"Jalaranu - pengembangan proyek datacenter bawah danau untuk ketahanan digital Indonesia. Proyek ini mengevaluasi efisiensi termal, keandalan operasi, dan dampak lingkungan melalui program bertahap berbasis bukti sebelum ada komitmen konstruksi.","copyright":"Jalaranu","logoAlt":"Jalaranu","ogImageAlt":"Wordmark Jalaranu pada latar gelap dengan tajuk Infrastruktur komputasi di bawah danau.","skipLink":"Langsung ke konten utama","menuToggle":"Buka atau tutup menu","socialFollow":"Ikuti Jalaranu","social":{"instagram":"https://instagram.com/projectjalaranu","x":"https://x.com/projectjalaranu","linkedin":"https://linkedin.com/company/jalaranu","facebook":"https://www.facebook.com/jalaranu","tiktok":"https://www.tiktok.com/@jalaranu","github":"https://github.com/jalaranu"},"languageSwitch":"Ganti bahasa ke","languageMenu":"Bahasa","languages":{"en":"English","id":"Bahasa Indonesia"},"carouselPrev":"Slide sebelumnya","carouselNext":"Slide berikutnya","carouselPause":"Jeda tampilan","carouselPlay":"Putar tampilan","carouselGoTo":"Ke slide","carouselSlides":"Slide gambar utama","brandSlogan":"Dingin, sunyi, jagat data lestari. Proyek datacenter bawah danau pertama di dunia."},"nav":{"technology":"Teknologi","useCases":"Use Cases","validation":"Milestone","partnerships":"Kemitraan","about":"Tentang","primaryCta":"Diskusikan Kemitraan"},"pages":{"home":{"seoTitle":"Jalaranu | Proyek Datacenter Bawah Danau","seoDescription":"Jelajahi proyek datacenter bawah danau pertama di dunia: pendekatan validasi Jalaranu dan peluang kemitraan untuk infrastruktur komputasi di Indonesia.","hero":{"eyebrow":"Proyek datacenter bawah danau","h1":"Infrastruktur komputasi **bawah danau** untuk ==ketahanan digital Indonesia==.","intro":["Jalaranu mengembangkan datacenter bawah danau modular ramah lingkungan pertama di dunia untuk mengevaluasi efisiensi termal, keandalan operasi, dan kelayakan penerapan di Indonesia.","Kami membuka ruang kolaborasi bagi investor, institusi, dan mitra teknologi untuk membangun dasar pengembangan yang terukur."],"primaryCta":{"label":"Diskusikan Kemitraan","to":"/id/partnerships/#contact"},"secondaryCta":{"label":"Jelajahi Teknologi","to":"/id/technology/"},"caption":"Ilustrasi proyek. Konfigurasi akhir mengikuti hasil studi dan rekayasa.","imageAlt":"Ilustrasi proyek Jalaranu: modul datacenter di bawah permukaan danau yang terhubung ke fasilitas pendukung di darat melalui jalur daya dan komunikasi yang terlindung.","slides":[{"src":"/assets/hero/danau-batur.webp","alt":"Danau Batur, Bali, dilihat dari tepian vulkaniknya"},{"src":"/assets/hero/danau-matano.webp","alt":"Danau Matano, Sulawesi Selatan, danau purba berair dalam"}]},"why":{"h2":"Mengapa mempertimbangkan **bawah danau**?","body":["Penempatan bawah danau menawarkan pendekatan yang berbeda terhadap pengelolaan panas, ruang fisik, dan akses ke infrastruktur. Manfaatnya perlu dinilai bersama konsekuensi pemasangan, pemeliharaan, konektivitas, dan pemulihan.","Pertanyaan utamanya: pada kondisi apa pendekatan ini lebih layak daripada datacenter darat dengan pendinginan berbasis air?","Jalaranu menempatkan perbandingan tersebut sebagai dasar evaluasi."],"focuses":[{"title":"Kinerja termal","body":"**Menilai perpindahan panas** dan kebutuhan energi pada kondisi lokasi dan beban yang ditentukan."},{"title":"Keandalan operasi","body":"**Menguji bagaimana sistem dipantau, dipelihara, dan dipulihkan** ketika terjadi gangguan."},{"title":"Kelayakan menyeluruh","body":"**Membandingkan biaya sepanjang umur fasilitas** serta tanggung jawab terhadap lingkungan."}],"cta":{"label":"Lihat Milestone","to":"/id/milestones/"}},"system":{"h2":"Satu sistem, dari darat hingga modul bawah danau.","body":"Proyek Jalaranu menghubungkan fasilitas pendukung di darat dengan modul komputasi di bawah air. Perencanaan mencakup daya, konektivitas, pengelolaan panas, pemantauan, serta cara modul dipasang dan diambil kembali.","items":[{"title":"Fasilitas darat","body":"Antarmuka daya, jaringan, dan pengelolaan operasi."},{"title":"Hubungan darat–modul","body":"Jalur daya dan komunikasi yang perlu dirancang bersama kebutuhan kontinuitas layanan."},{"title":"Modul bawah danau","body":"Wadah komputasi dan sistem pendukung yang akan dievaluasi melalui rekayasa dan pengujian."},{"title":"Pemantauan dan pemulihan","body":"Pengamatan kondisi sistem, penanganan gangguan, dan pengambilan kembali modul."}],"cta":{"label":"Pelajari Proyek","to":"/id/technology/#system"}},"validation":{"h2":"Kemajuan yang dinilai melalui bukti.","body":["Setiap tahap pengembangan perlu menjawab pertanyaan yang spesifik: apakah kinerjanya sesuai kebutuhan, bagaimana sistem berperilaku saat gagal, berapa biaya operasinya, dan bagaimana dampaknya terhadap lingkungan dinilai?","Rencana pengujian, hasil pengukuran, dan keterbatasannya menjadi dasar keputusan untuk melanjutkan pengembangan."],"cta":{"label":"Jelajahi Milestone","to":"/id/milestones/"}},"partnerships":{"h2":"Bangun tahap berikutnya bersama Jalaranu.","tracks":[{"title":"Investor","body":"Menjajaki pendanaan berbasis milestone dan evaluasi model bisnis."},{"title":"Pemerintah dan pertahanan","body":"Membahas kebutuhan penggunaan, persyaratan evaluasi, dan kemungkinan pengembangan pilot."},{"title":"Mitra industri","body":"Mengeksplorasi kontribusi pada rekayasa, energi, jaringan, manufaktur, dan operasi."},{"title":"Mitra riset","body":"Menyusun metode pengujian dan kajian teknis, ekonomi, serta lingkungan."}],"cta":{"label":"Temukan Jalur Kemitraan","to":"/id/partnerships/"}},"closing":{"h2":"Apa yang perlu ==dibuktikan agar proyek ini relevan== bagi organisasi Anda?","body":"Mari mulai dari kebutuhan, ruang lingkup evaluasi, dan kontribusi yang dapat dibangun bersama.","cta":{"label":"Diskusikan Kemitraan","to":"/id/partnerships/#contact"}}},"technology":{"seoTitle":"Teknologi Datacenter Bawah Danau | Jalaranu","seoDescription":"Pelajari proyek datacenter bawah danau pertama di dunia: dari fasilitas darat dan modul komputasi hingga pengelolaan panas, konektivitas, serta pemulihan.","hero":{"h1":"Rekayasa yang dimulai dari pertanyaan yang tepat.","body":"Jalaranu mengeksplorasi datacenter bawah danau sebagai **satu sistem utuh**. Penempatan modul perlu dievaluasi bersama daya, jaringan, pengelolaan panas, pemeliharaan, dan pemulihannya."},"architecture":{"h2":"Dari antarmuka darat ke lingkungan bawah air.","body":["Arsitektur proyek mencakup empat bagian: fasilitas pendukung darat, jalur daya dan komunikasi, modul komputasi, serta sistem pemantauan dan pengelolaan operasi. Keterkaitan antarbagiannya menentukan bagaimana keseluruhan fasilitas dapat bekerja dan dipulihkan.","Visualisasi awal menggunakan bentuk limas segi empat terpancung. Bentuk tersebut merupakan eksplorasi desain; geometri, material, dan spesifikasi akhir mengikuti hasil rekayasa serta pengujian."],"anchor":"system","visualNote":"Diagram blok dan potongan, dengan jalur logis tanpa koordinat atau rincian pengamanan fasilitas.","imageAlt":"Gambar rekayasa modul limas segi empat terpancung: tampak depan, potongan A-A, denah rangka atap, dan detail sambungan kedap.","imageCaption":"Rancangan rekayasa berdimensi, bukan gambar fabrikasi."},"engineering":{"h2":"Lima bidang yang perlu dievaluasi.","items":[{"title":"Pengelolaan panas","body":"**Kondisi air, perpindahan panas**, beban komputasi, dan energi yang diperlukan sistem pendukung."},{"title":"Integritas modul","body":"**Kemampuan struktur, sambungan, serta antarmuka sistem** menghadapi kondisi operasi yang ditetapkan."},{"title":"Daya dan konektivitas","body":"**Kebutuhan layanan, pilihan redundansi**, perilaku ketika jalur terganggu, dan prosedur pemulihan."},{"title":"Pemeliharaan","body":"**Apa yang dapat dipantau dari jarak jauh**, kapan intervensi diperlukan, serta bagaimana modul ditangani atau diangkat."},{"title":"Keamanan dan kendali","body":"**Akses administratif, pemantauan kejadian, pengelolaan kunci**, tanggung jawab operator, serta perlindungan antarmuka fisik dan digital."}]},"comparison":{"h2":"Keunggulan harus dinilai terhadap alternatif yang relevan.","body":["Evaluasi perlu membandingkan proyek bawah danau dengan solusi darat pada kebutuhan layanan, beban, dan asumsi yang setara. Perbandingan mencakup fasilitas darat dengan pendinginan konvensional maupun pendinginan berbasis air, bila relevan untuk lokasi yang dikaji.","Aspek penilaian meliputi energi, biaya investasi, biaya operasi, pemeliharaan, konektivitas, pemulihan, dampak lingkungan, dan akhir masa pakai. Potensi penghematan pada satu komponen tidak dengan sendirinya menunjukkan biaya total yang lebih rendah."]},"placements":{"h2":"Alternatif penempatan, dibandingkan dengan jujur.","intro":["Proyek bawah danau dievaluasi terhadap tiga penempatan acuan pada tingkat layanan yang setara: fasilitas darat, bunker yang diperkuat, dan penempatan bawah laut. Setiap pertukaran di bawah ini adalah penilaian awal untuk diuji, bukan hasil pengukuran.","Model biaya sepuluh tahun pendamping pada tingkat layanan setara memberi 6,00 juta dolar untuk fasilitas darat dengan pendinginan konvensional, 6,34 untuk fasilitas darat yang diperkeras dengan pendinginan air danau, dan 7,85 untuk desain terendam. Submersion membeli kemampuan, bukan penghematan biaya."],"note":"Penilaian kerangka awal untuk diskusi. Angka dan peringkat memerlukan pengukuran serta kajian lokasi. Angka termal penyaringan (anomali rata-rata cekungan sekitar 0,001 kelvin selama lima puluh tahun dan jejak dua belas bulan 228-509 meter) berstatus belum terbukti sampai diukur.","table":{"rowHeading":"Kriteria","columns":[{"icon":"droplets","name":"Datacenter bawah danau","sub":"Danau air tawar"},{"icon":"waves","name":"Datacenter bawah laut","sub":"Penempatan laut"},{"icon":"building2","name":"Datacenter darat","sub":"Pendinginan konvensional"},{"icon":"shield-check","name":"Bunker diperkuat","sub":"Cangkang berpelindung"}],"rows":[{"icon":"history","label":"Kematangan operasi","values":["Prototipe dan pengujian sedang berlangsung","Terbukti di laut (Project Natick)","Terbukti beroperasi","Terbukti untuk beban kritis"]},{"icon":"shield","label":"Perlindungan fisik","values":["Lambung tekan, kolom air daratan","Cangkang diperkeras, lokasi jauh","Keamanan tapak, perimeter terbuka","Konstruksi diperkuat, akses terbatas"]},{"icon":"thermometer","label":"Pembuangan panas","values":["Pendinginan air pasif, anggaran termal belum diukur","Pendinginan air pasif","Pendinginan mekanis, biaya energi","Pembuangan panas ruang tertutup yang rumit"]},{"icon":"scale","label":"Yurisdiksi","values":["Perairan daratan domestik","Zona maritim yang diperebutkan","Domestik, koridor perkotaan","Domestik"]},{"icon":"landmark","label":"Permukaan ancaman darat","values":["Modul terendam, stasiun darat tetap terpapar","Jauh di laut, stasiun darat tetap terpapar","Akses perimeter langsung, keamanan tapak diperlukan","Diperkuat terhadap intrusi, akses terbatas"]},{"icon":"plane","label":"Permukaan ancaman udara","values":["Modul terlindung kolom air, stasiun darat terpapar","Dukungan permukaan terpapar di laut","Terpapar penuh dari udara","Diperkeras terhadap ancaman udara"]},{"icon":"anchor","label":"Permukaan ancaman maritim","values":[{"text":"Di luar jangkauan kapal selam","highlight":true},"Penyadapan kabel kapal selam, seret jangkar","Tidak ada","Tidak ada"]},{"icon":"boxes","label":"Skalabilitas","values":["Modul terbatas danau","Modul terbatas lokasi","Klaster hiperskala","Lebih sulit diskalakan"]},{"icon":"dollar-sign","label":"Model biaya sepuluh tahun","values":["$7,85 juta","Belum dimodelkan","$6,00 juta","$6,34 juta"]},{"icon":"flask-conical","label":"Status bukti","values":["Dihitung","Pilot terbukti","Terukur","Terukur"]}]}},"scenarios":{"h2":"Skenario penggunaan yang dieksplorasi","body":["Proyek ini dapat dievaluasi untuk komputasi khusus, penyimpanan, atau kebutuhan infrastruktur tertentu berdasarkan persyaratan organisasi. Kesesuaian setiap skenario harus ditentukan melalui evaluasi kebutuhan dan bukti pengujian.","Penyebutan skenario penggunaan bukan pernyataan bahwa layanan tersebut sudah tersedia atau telah disetujui untuk menangani data sensitif."],"cta":{"label":"Bahas Kebutuhan Teknis","to":"/id/partnerships/#contact"}},"indexLabel":"Di halaman ini","indexMoreLabel":"Bagian lainnya","index":[{"id":"system","label":"Arsitektur proyek"},{"id":"inside","label":"Di Dalam Jalaranu"},{"id":"comparison","label":"Membandingkan alternatif"},{"id":"placements","label":"Perbandingan penempatan"},{"id":"scenarios","label":"Skenario penggunaan"}],"inside":{"h2":"Di Dalam Jalaranu","anchor":"inside","intro":["Struktur acuan memecah modul menjadi 24 komponen bernomor dalam enam sistem. Figur ini adalah rancangan rekayasa berdimensi, bukan gambar fabrikasi."],"items":[{"title":"Selubung pelindung","body":"Cangkang baja tahan karat, pengaku struktural, dan pelindung antikorosi yang ditopang skid ballast. Beban pengangkatan melewati empat padeye atas, sementara tutup servis menjaga dua seal yang dipisahkan ruang antar-seal terpantau."},{"title":"Kaset komputasi","body":"Kaset 8U menampung tiga server 2U dengan penyimpanan SSD/NVMe dan switch jaringan, di bawah usulan atmosfer nitrogen dengan kelembapan terkendali serta penetrator daya A/B dan serat optik."},{"title":"Sirkuit pendinginan","body":"Coil gas-cairan dan kipas memindahkan panas ke sirkuit coolant tertutup melalui pompa A/B dan penukar panas eksternal A/B. Katup isolasi memisahkan cabang, dan air danau tidak pernah bercampur dengan coolant internal."},{"title":"Ketahanan daya","body":"UPS baterai LiFePO4 opsional ditempatkan di ruang bawah yang terpisah dari perangkat komputasi, dengan target cadangan sepuluh menit pada beban asumsi 2,1 kW."},{"title":"Isolasi getaran","body":"Empat isolator captive dengan snubber berperedam menopang kaset server, dengan sambungan fleksibel, bonding listrik, serta pengunci transportasi dan servis."},{"title":"Pemantauan dan keselamatan","body":"Sensor temperatur, kelembapan, oksigen, tekanan, dan gerak, kamera dengan jendela dan wiper, serta tray pendeteksi kebocoran memberi masukan bagi distribusi daya dan kontrol keselamatan."}],"note":"Seluruh nilai adalah asumsi desain, bukan hasil pengukuran. Kedap air, kedalaman operasi, kapasitas angkat, dan ketahanan gempa harus ditetapkan melalui analisis dan pengujian rakitan terintegrasi."}},"useCases":{"seoTitle":"Use Cases: Data Strategis & Layanan Kritikal | Jalaranu","seoDescription":"Jelajahi use case Jalaranu untuk informasi berklasifikasi, pemulihan layanan, dukungan pangkalan, analisis strategis, komputasi, dan arsip penting.","indexLabel":"Di halaman ini","indexMoreLabel":"Bagian lainnya","index":[{"id":"data","label":"Data yang dilindungi"},{"id":"use-cases","label":"Use case"},{"id":"mapping","label":"Peta sektor"},{"id":"needs","label":"Kebutuhan lintas sektor"},{"id":"approach","label":"Pendekatan evaluasi"}],"hero":{"eyebrow":"Use Cases · Data strategis dan layanan kritikal","h1":"Untuk data yang harus tetap terlindungi. Untuk layanan yang harus ==tetap berjalan==.","intro":["Dari informasi strategis negara hingga layanan keuangan dan infrastruktur vital, setiap sektor memiliki kebutuhan berbeda dalam menjaga kerahasiaan, integritas, dan ketersediaan data.","Jalaranu mengembangkan konsep datacenter bawah danau untuk mengeksplorasi pendekatan perlindungan fisik, penempatan infrastruktur, dan kesinambungan layanan bagi kebutuhan tersebut.","Temukan use case yang sesuai dengan kebutuhan Anda dan diskusikan persyaratan yang perlu dibuktikan bersama."],"primaryCta":{"label":"Diskusikan Kebutuhan Infrastruktur","to":"/id/partnerships/#contact"},"secondaryCta":{"label":"Pelajari Pendekatan Milestone","to":"/id/milestones/"}},"data":{"h2":"Nilai informasi menentukan kebutuhan perlindungannya.","intro":["Informasi berklasifikasi membutuhkan pengendalian terhadap akses dan pengungkapan. Data kritikal membutuhkan integritas serta ketersediaan untuk menopang fungsi penting. Satu kumpulan data dapat memiliki kedua karakteristik tersebut."],"illustrationAlt":"Ilustrasi konsep datacenter Jalaranu di bawah danau, terhubung dengan fasilitas pendukung di darat.","illustrationCaption":"Ilustrasi konsep. Konfigurasi akhir bergantung pada hasil studi dan rekayasa.","tableHeaderRequirement":"Kebutuhan","tableHeaderFocus":"Fokus perlindungan","tableHeaderApplications":"Contoh pemanfaatan","rows":[{"icon":"lock","requirement":"**Informasi berklasifikasi dan rahasia negara**","focus":"Kerahasiaan, pembatasan akses, kendali pengelolaan, dan penanganan sesuai kewenangan.","applications":"Dokumen pertahanan, informasi intelijen, arsip diplomatik, serta dokumen strategis yang ditetapkan berklasifikasi."},{"icon":"database","requirement":"**Data dan layanan kritikal**","focus":"Integritas, ketersediaan, dan kemampuan pemulihan ketika terjadi gangguan.","applications":"Data transaksi, aplikasi pelayanan publik, serta sistem informasi pendukung energi dan transportasi."},{"icon":"layers","requirement":"**Aset informasi strategis**","focus":"Perlindungan terhadap kehilangan, perubahan tanpa izin, dan akses yang tidak berwenang.","applications":"Data eksplorasi, desain industri, hasil penelitian, kekayaan intelektual, dan arsip penting negara."}]},"explore":{"h2":"Mulai dari fungsi yang perlu dilindungi dan didukung.","intro":["Satu kebutuhan dapat ditemukan di beberapa sektor. Delapan use case berikut menjadi titik awal untuk menentukan data, layanan, dan persyaratan yang perlu dievaluasi bersama Jalaranu."],"cardsLabel":"Pilih use case untuk melompat ke penjelasannya.","sectorsLabel":"Sektor terkait","applicationsLabel":"Contoh pemanfaatan","objectiveLabel":"Tujuan","validateLabel":"Yang perlu divalidasi","cards":[{"id":"classified","icon":"lock","title":"Perlindungan Informasi Berklasifikasi & Rahasia Negara","titleEn":"Classified Information & State Secrets","sectors":["Pertahanan","Intelijen","Pemerintahan"],"body":"Lingkungan penyimpanan dan pengolahan bagi informasi yang pengungkapan atau perubahannya dapat memengaruhi kepentingan strategis negara.","applications":["Dokumen pertahanan, informasi intelijen, dan arsip diplomatik sesuai klasifikasi serta kewenangan.","Dokumen kebijakan strategis yang secara resmi ditetapkan berklasifikasi.","Pemisahan lingkungan pengolahan, pengendalian akses, dan jejak audit.","Salinan pemulihan informasi sensitif dengan pengelolaan akses dan kunci yang ditetapkan institusi."],"objective":"Menjaga kerahasiaan, integritas, dan kendali institusi atas informasi.","toValidate":"Persyaratan klasifikasi, otorisasi personel, pengelolaan kunci, pemisahan sistem, dan pengamanan fisik maupun digital."},{"id":"recovery","icon":"life-buoy","title":"Pemulihan Bencana & Insiden Siber","titleEn":"Disaster & Cyber Recovery","sectors":["Keuangan","Pemerintahan","Kesehatan","Telekomunikasi","Energi","Transportasi","Pertahanan"],"body":"Kapasitas pemulihan untuk data dan aplikasi ketika layanan utama terganggu oleh insiden fisik, kegagalan fasilitas, atau insiden siber.","applications":["Salinan tambahan data transaksi, data administrasi, rekam kesehatan, dan data pendukung operasi.","Lingkungan pemulihan yang akses dan dependensinya dipisahkan dari sistem utama.","Pemulihan aplikasi pelayanan publik, sistem rumah sakit, serta layanan operator.","Pengujian pemulihan data dan aplikasi secara berkala, termasuk pemeriksaan integritas data."],"objective":"Memulihkan fungsi prioritas dalam sasaran waktu dan kehilangan data yang dapat diterima.","toValidate":"Sasaran pemulihan, perbedaan eksposur risiko, dependensi daya dan jaringan, isolasi cadangan, dan hasil uji pemulihan. Replika saja belum menjamin pemulihan dari insiden siber."},{"id":"base-support","icon":"radio","title":"Dukungan Digital Pangkalan & Kesiapan Pertahanan","titleEn":"Base Support & Defence Readiness","sectors":["Militer & pertahanan"],"body":"Komputasi, penyimpanan, dan aplikasi pendukung bagi pangkalan tetap maupun **Forward Operating Base (FOB)**, sesuai kebutuhan penempatan dan konektivitas.","applications":["Layanan digital pendukung FOB dan pangkalan tetap.","Infrastruktur bagi sistem informasi komando dan koordinasi.","Pengelolaan logistik, inventaris, pemeliharaan, dan kesiapan aset.","Lingkungan simulasi, pelatihan, penelitian, dan pengujian.","Penyimpanan serta pemulihan data pendukung pangkalan."],"objective":"Mendukung ketersediaan informasi dan kesinambungan layanan yang menopang kesiapan pertahanan.","toValidate":"Kebutuhan layanan setempat, klasifikasi data, kendali operasional, dependensi komunikasi, serta prosedur pemeliharaan dan pemulihan."},{"id":"analytics","icon":"radar","title":"Analisis Strategis & Pengolahan Data Geospasial","titleEn":"Strategic Analytics & Geospatial Processing","sectors":["Intelijen","Pertahanan","Pemerintahan","Energi","Maritim","Logistik"],"body":"Lingkungan pengolahan untuk mengubah kumpulan data besar menjadi informasi yang mendukung analisis dan pengambilan keputusan.","applications":["Pengolahan dan penyimpanan citra, data geospasial, serta data intelijen, pengawasan, dan pengintaian (ISR) sesuai kewenangan.","Analisis sumber terbuka dan informasi lain yang diperoleh secara sah.","Analisis risiko ekonomi, energi, rantai pasok, dan infrastruktur.","Pengolahan informasi lingkungan maritim dan perencanaan logistik.","Ruang kerja analitis dengan pemisahan akses dan jejak audit."],"objective":"Menyediakan kapasitas pengolahan dan tata kelola data bagi analisis strategis.","toValidate":"Asal serta kewenangan penggunaan data, kebutuhan komputasi, latensi, integritas, dan pemisahan lingkungan kerja."},{"id":"research","icon":"cpu","title":"Komputasi Riset, Pemodelan & Simulasi","titleEn":"Research Computing, Modelling & Simulation","sectors":["Energi","Keuangan","Kesehatan","Pertahanan","Universitas","Lembaga riset"],"body":"Kapasitas komputasi bagi pekerjaan analitis dan ilmiah yang memerlukan pengolahan data intensif.","applications":["Pengolahan data seismik, pemodelan reservoir, serta simulasi energi dan proses industri.","Pemodelan risiko, stress testing, komputasi aktuaria, dan analitik fraud.","Pengolahan data genomik, citra medis, dan dataset penelitian sesuai kewenangan.","Simulasi teknik, penelitian pertahanan, dan lingkungan pengujian.","Infrastruktur riset bersama universitas dan laboratorium."],"objective":"Mendukung pengolahan data dan eksperimen dengan kapasitas yang sesuai kebutuhan.","toValidate":"Profil pekerjaan, perangkat komputasi, daya, pelepasan panas, pemindahan data, kebutuhan pemeliharaan, dan biaya sepanjang umur fasilitas."},{"id":"regional","icon":"server","title":"Komputasi Regional & Layanan Digital","titleEn":"Regional Computing & Digital Services","sectors":["Telekomunikasi","Operator infrastruktur digital","Pemerintahan","Mitra layanan regional"],"body":"Penempatan kapasitas komputasi dan penyimpanan untuk melayani kebutuhan pengguna serta aplikasi di suatu wilayah.","applications":["Hosting aplikasi dan penyimpanan regional.","Aplikasi pengelolaan jaringan, pemantauan layanan, dan analitik operator.","Cache konten ketika pola permintaan dan konektivitas mendukung.","Infrastruktur komputasi khusus bagi kebutuhan mitra.","Kapasitas tambahan dan replika layanan digital."],"objective":"Menyediakan kapasitas di lokasi yang sesuai dengan permintaan dan arsitektur jaringan.","toValidate":"Konektivitas nyata, latensi, kapasitas jaringan, jalur alternatif, kebutuhan pengguna, dan kelayakan ekonomi lokasi."},{"id":"operations","icon":"clipboard-list","title":"Dukungan Operasi & Pengelolaan Aset","titleEn":"Operational Support & Asset Management","sectors":["Energi","Transportasi","Maritim","Logistik","Pertahanan"],"body":"Infrastruktur informasi untuk merencanakan, memantau, dan memelihara aset serta layanan pendukung operasional.","applications":["Analisis riwayat operasi dan pemeliharaan prediktif.","Aplikasi informasi pendukung pelabuhan, distribusi, dan rantai pasok.","Pengelolaan armada, inventaris, kapasitas, dan kesiapan aset.","Penyimpanan desain fasilitas serta dokumentasi teknis.","Replika dan pemulihan aplikasi pendukung operasi."],"objective":"Menjaga akses terhadap informasi yang dibutuhkan untuk mengelola aset dan kesinambungan kegiatan.","toValidate":"Integrasi sistem, kualitas data, konektivitas, dan pemisahan dari fungsi kendali waktu nyata atau keselamatan."},{"id":"archives","icon":"archive","title":"Arsip Strategis & Perlindungan Kekayaan Intelektual","titleEn":"Strategic Archives & Intellectual Property Protection","sectors":["Pemerintahan","Energi","Keuangan","Kesehatan","Industri","Lembaga riset"],"body":"Penyimpanan terkelola untuk informasi yang harus tetap utuh, dapat ditelusuri, dan dapat diakses oleh pihak berwenang sepanjang masa retensinya.","applications":["Arsip penting negara, arsip pertanahan, dan data administrasi.","Data eksplorasi, geologi, cadangan sumber daya, dan desain industri.","Arsip audit serta bukti transaksi dengan pengendalian integritas.","Hasil penelitian, data medis, dan kekayaan intelektual sesuai tata kelola masing-masing.","Pemeriksaan integritas, pengujian pengambilan kembali, dan migrasi media atau format."],"objective":"Menjaga nilai informasi dalam jangka panjang serta mendukung penelusuran dan penggunaan kembali.","toValidate":"Kebijakan retensi, hak akses, kapasitas, waktu pengambilan kembali, integritas, dan rencana migrasi teknologi."}]},"mapping":{"h2":"Peta sektor dan use case","intro":["Satu kebutuhan dapat muncul di beberapa sektor. Pemetaan berikut menghubungkan contoh kebutuhan utama setiap sektor dengan use case terkait."],"tableHeaderSector":"Sektor","tableHeaderRequirements":"Contoh kebutuhan utama","tableHeaderUseCases":"Use case terkait","rows":[{"sector":"Pertahanan & militer","requirements":"Informasi berklasifikasi, dukungan FOB dan pangkalan, kesiapan aset","useCases":[1,2,3,4,5,7]},{"sector":"Intelijen & keamanan nasional","requirements":"Informasi sensitif dan analisis strategis","useCases":[1,2,4]},{"sector":"Pemerintahan","requirements":"Rahasia negara, layanan publik, arsip negara","useCases":[1,2,4,6,8]},{"sector":"Energi & sumber daya","requirements":"Data eksplorasi, simulasi, operasi aset","useCases":[2,4,5,7,8]},{"sector":"Perbankan & jasa keuangan","requirements":"Pemulihan layanan, komputasi risiko, bukti transaksi","useCases":[2,5,8]},{"sector":"Telekomunikasi & infrastruktur digital","requirements":"Kapasitas regional dan kesinambungan layanan","useCases":[2,6]},{"sector":"Transportasi, maritim & logistik","requirements":"Informasi operasional, geospasial, pengelolaan aset","useCases":[2,4,7]},{"sector":"Kesehatan & riset strategis","requirements":"Data sensitif, pemulihan sistem, komputasi ilmiah","useCases":[2,5,8]}]},"needs":{"h2":"Empat kebutuhan yang menghubungkan seluruh sektor.","items":[{"icon":"key-round","title":"Perlindungan informasi sensitif","body":"Menentukan siapa yang berwenang mengakses, mengelola, dan memproses data. Persyaratan perlindungan perlu mengikuti klasifikasi informasi dan tanggung jawab institusi."},{"icon":"shield","title":"Ketahanan terhadap gangguan fisik","body":"Mengevaluasi bagaimana lokasi, penempatan, dan desain fasilitas memengaruhi eksposur risiko. Perlindungan modul perlu dipertimbangkan bersama daya, konektivitas, fasilitas pendukung, dan pemulihan."},{"icon":"rotate-ccw","title":"Kesinambungan dan pemulihan","body":"Menetapkan data serta layanan yang perlu dipertahankan, bagaimana pemulihan dilakukan, dan bagaimana keberhasilannya diuji ketika fasilitas atau suatu wilayah mengalami gangguan."},{"icon":"user-cog","title":"Kendali operasional","body":"Memperjelas pihak yang mengoperasikan sistem, mengelola akses dan kunci, mengendalikan pemasok, serta bertanggung jawab atas layanan."}]},"approach":{"h2":"Dimulai dari kebutuhan. Dilanjutkan dengan pembuktian.","body":["Kesesuaian penempatan bawah danau perlu dinilai berdasarkan kebutuhan organisasi, kondisi lokasi, serta alternatif yang relevan."],"flowLabel":"Alur evaluasi","flowCaption":"Gambaran konseptual alur evaluasi. Kesesuaian ditetapkan melalui bukti, bukan asumsi.","flow":[{"icon":"search","title":"Penilaian kebutuhan","body":"Data, layanan, dampak, dan persyaratan kendali yang perlu didukung."},{"icon":"flask-conical","title":"Validasi teknis","body":"Pengujian kelayakan teknis, ekonomi, dan lingkungan."},{"icon":"key-round","title":"Pemenuhan persyaratan institusi","body":"Persyaratan akses, klasifikasi, dan tata kelola institusi terkait."},{"icon":"scale","title":"Penetapan kesesuaian","body":"Keputusan berbasis bukti mengenai kecocokan dan langkah berikutnya."}],"discussionIntro":"Pembahasan awal mencakup:","discussion":["Jenis data dan fungsi layanan yang akan didukung.","Dampak kebocoran, perubahan, kehilangan, atau ketidaktersediaan data.","Persyaratan akses, pengelolaan, dan kendali operasional.","Sasaran pemulihan dan ketergantungan pada daya serta jaringan.","Pengujian yang dibutuhkan untuk menilai kelayakan teknis, ekonomi, dan lingkungan."],"scopeTitle":"Keterangan lingkup","scope":"Kesesuaian untuk informasi berklasifikasi dan layanan kritikal ditentukan melalui evaluasi kebutuhan, validasi teknis, serta pemenuhan persyaratan institusi terkait.","cta":{"label":"Pelajari Pendekatan Milestone","to":"/id/milestones/"}},"closing":{"h2":"Informasi apa yang harus tetap terlindungi ketika kondisi ==berubah==?","body":"Mari mulai dari kebutuhan organisasi Anda: data yang harus dijaga, layanan yang harus dipulihkan, dan persyaratan yang perlu dipenuhi.","helperText":"Sampaikan konteks umum terlebih dahulu. Jangan mengirim informasi rahasia, kredensial, atau dokumen terbatas melalui formulir publik.","cta":{"label":"Diskusikan Kebutuhan Infrastruktur","to":"/id/partnerships/#contact"}}},"validation":{"seoTitle":"Milestone Pengembangan | Jalaranu","seoDescription":"Kenali cara proyek datacenter bawah danau pertama di dunia divalidasi: pertanyaan pengujian dan pendekatan evaluasi bertahap.","hero":{"h1":"Bukti menjadi dasar untuk melangkah.","body":"Kelayakan datacenter bawah danau perlu dinilai secara **teknis, ekonomi, dan lingkungan**. Pendekatan validasi Jalaranu berfokus pada pertanyaan yang dapat diuji, metode yang dapat dijelaskan, serta hasil yang disampaikan bersama batasannya."},"status":{"h2":"Status pengembangan","items":["Jalaranu kini berada pada tahap prototipe dan pengujian. Tahap saat ini diumumkan di sini dan akan terus diperbarui.","Pertanyaan pengujian, metode, dan bukti apa pun yang disetujui untuk dibagikan akan dipublikasikan begitu tersedia."]},"plan":{"h2":"Pertanyaan yang membentuk rencana pengujian.","body":"Kriteria keberhasilan, metode, dan tanggung jawab ditetapkan sebelum setiap langkah pengujian, agar setiap hasil dapat dinilai terhadap kriteria yang dipublikasikan.","table":[{"area":"Termal dan energi","question":"Bagaimana sistem bekerja pada rentang beban dan kondisi lingkungan yang ditetapkan?"},{"area":"Struktur dan integritas","question":"Apakah modul serta antarmukanya memenuhi kondisi operasi dan pengujian yang ditentukan?"},{"area":"Keandalan dan pemulihan","question":"Bagaimana sistem merespons gangguan, dipulihkan, dan dipelihara?"},{"area":"Biaya sepanjang umur fasilitas","question":"Bagaimana biaya pemasangan, operasi, intervensi, pengambilan kembali, dan akhir masa pakai dibanding alternatif?"},{"area":"Lingkungan","question":"Bagaimana kondisi awal didokumentasikan, perubahan dipantau, dan hasilnya dievaluasi?"},{"area":"Kesesuaian penggunaan","question":"Untuk kebutuhan dan tingkat layanan apa hasil pengujian menunjukkan kecocokan?"}],"tableHeaderArea":"Bidang","tableHeaderQuestion":"Pertanyaan evaluasi"},"framework":{"h2":"Pengembangan bertahap, dengan keputusan pada setiap tahap.","steps":[{"title":"Perumusan kebutuhan","body":"Menetapkan tujuan, alternatif pembanding, dan kriteria keberhasilan."},{"title":"Studi dan rekayasa awal","body":"Menilai lokasi yang layak dikaji, risiko, rancangan sistem, serta asumsi biaya."},{"title":"Pengujian komponen dan integrasi","body":"Menguji fungsi yang menentukan keselamatan dan kinerja sistem."},{"title":"Pilot terbatas","body":"Mengukur kinerja pada lingkup yang disepakati, dengan rencana pemantauan dan pemulihan."},{"title":"Evaluasi untuk tahap berikutnya","body":"Menilai hasil, kekurangan, dan kelayakan pengembangan lebih lanjut."}],"note":"Urutan ini adalah kerangka pengembangan, bukan daftar tahap yang dinyatakan telah selesai."},"environment":{"h2":"Komitmen lingkungan","body":["Kajian lokasi perlu mempertimbangkan kondisi perairan, penggunaan kawasan, kebutuhan masyarakat terkait, serta persyaratan yang berlaku. Rencana evaluasi harus mencakup kondisi awal, perubahan yang dipantau selama pengujian, dan penanganan fasilitas pada akhir masa pakai.","Hasil kajian menjadi masukan untuk keputusan lokasi dan desain, termasuk keputusan untuk tidak melanjutkan suatu opsi bila tidak layak."],"items":[{"title":"Disiplin ekologis","body":"Danau adalah sumber daya pembatas; manfaat lingkungan tidak pernah diklaim tanpa pengukuran."},{"title":"Anggaran termal yang dipublikasikan","body":"Perhitungan penyaringan memberi anomali rata-rata cekungan sekitar 0,001 kelvin selama lima puluh tahun dan jejak setara panas dua belas bulan 228-509 meter. Keduanya berstatus belum terbukti sampai diukur di lokasi kandidat."},{"title":"Baseline sebelum penempatan","body":"Kondisi awal, kondisi air, penggunaan kawasan, dan kebutuhan masyarakat terdampak menjadi bagian dari rencana evaluasi."},{"title":"Akhir masa pakai","body":"Pengakhiran, pengambilan kembali, dan pemulihan danau direncanakan sejak awal."},{"title":"Tidak melanjutkan tetap sah","body":"Jika bukti tidak mencukupi, opsi disingkirkan alih-alih dipaksakan."}]},"results":{"h2":"Ringkasan hasil dan dokumen","body":"Dokumen dan hasil yang dapat dibagikan akan ditampilkan setelah tersedia dan disetujui untuk publikasi.","cta":{"label":"Diskusikan Program","to":"/id/partnerships/#contact"}},"faq":[{"q":"Apakah Jalaranu sudah beroperasi secara komersial?","a":"**Website ini memperkenalkan proyek dan peluang pengembangan Jalaranu.** Ketersediaan layanan komersial akan disampaikan secara terpisah setelah kesiapan fasilitas dan layanannya dikonfirmasi."},{"q":"Mengapa menggunakan danau?","a":"**Danau merupakan konteks penempatan yang sedang dieksplorasi.** Kesesuaiannya perlu dinilai berdasarkan kondisi perairan, akses, energi, jaringan, lingkungan, dan kebutuhan penggunaan. Pemilihan danau tidak dengan sendirinya membuktikan keunggulan terhadap lokasi atau desain lain."},{"q":"Apakah pendinginannya gratis atau tanpa energi?","a":"**Potensi pemanfaatan lingkungan perairan harus dinilai bersama sistem perpindahan panas dan kebutuhan energi seluruh fasilitas.** Jalaranu belum menyatakan penghematan tertentu tanpa hasil pengukuran dan pembanding yang jelas."},{"q":"Bagaimana jika modul memerlukan perbaikan?","a":"**Kemampuan pemantauan, penanganan gangguan, pengambilan kembali, dan penggantian komponen merupakan bagian dari evaluasi desain.** Prosedur rinci akan mengikuti rancangan yang telah diuji serta kebutuhan layanan yang disepakati."},{"q":"Apakah dapat digunakan untuk data sensitif atau kebutuhan pertahanan?","a":"**Kesesuaian penggunaan perlu dievaluasi berdasarkan klasifikasi data, arsitektur sistem, kontrol akses, tata kelola, dan persyaratan institusi terkait.** Website ini tidak menyatakan persetujuan atau kesiapan untuk menangani informasi dengan klasifikasi tertentu."},{"q":"Bagaimana dampak terhadap danau dinilai?","a":"**Pendekatan kajian mencakup kondisi awal, perubahan yang perlu dipantau, serta evaluasi selama pengujian dan pada akhir masa pakai.** Ruang lingkupnya harus disesuaikan dengan lokasi dan kegiatan yang direncanakan."},{"q":"Bagaimana memperoleh informasi lebih lanjut?","a":"**Gunakan formulir kemitraan untuk menjelaskan organisasi dan tujuan diskusi.** Informasi yang dapat dibagikan akan ditentukan berdasarkan kebutuhan pembahasan dan ketersediaan dokumen."}],"faqTitle":"Pertanyaan yang sering diajukan"},"partnerships":{"seoTitle":"Kemitraan Pengembangan Datacenter | Jalaranu","seoDescription":"Jajaki kerja sama bersama Jalaranu sebagai investor, institusi pemerintah atau pertahanan, mitra industri, maupun mitra riset.","hero":{"h1":"Mulai dari kebutuhan. Sepakati apa yang perlu dibuktikan.","body":"Jalaranu membuka percakapan dengan pihak yang ingin menilai, mengembangkan, atau mendukung proyek datacenter bawah danau. Kerja sama dimulai dengan **tujuan yang jelas, lingkup yang realistis, hasil yang dapat dievaluasi**."},"tracks":[{"id":"investor","h2":"Pendanaan yang dikaitkan dengan kemajuan terukur.","body":["Kami mengundang pembahasan tentang kebutuhan pasar, model bisnis, tahapan pendanaan, dan bukti yang perlu dihasilkan pada setiap tahap. Fokus awalnya adalah memahami bagaimana modal dapat digunakan untuk mengurangi ketidakpastian pengembangan.","Ruang pembahasan mencakup calon pengguna, alternatif yang tersedia, estimasi biaya beserta asumsi, kebutuhan modal, serta milestone untuk keputusan investasi berikutnya."],"cta":{"label":"Bahas Peluang Investasi","formPreset":"investor"}},{"id":"institution","h2":"Evaluasi kebutuhan strategis melalui kerja sama yang terarah.","body":["Pembahasan dapat dimulai dari kebutuhan infrastruktur, kontinuitas layanan, kendali operasional, tata kelola data, dan kriteria evaluasi institusi. Kesesuaian proyek Jalaranu ditentukan melalui kajian kebutuhan dan pengujian yang relevan.","Kemungkinan ruang kerja sama mencakup studi kelayakan, penyusunan kebutuhan, dan pengembangan pilot terbatas. Persyaratan akses, penanganan informasi, serta tanggung jawab masing-masing pihak disepakati sesuai lingkup kerja sama."],"cta":{"label":"Jajaki Kerja Sama Institusi","formPreset":"institution"}},{"id":"industry","h2":"Menghubungkan kemampuan rekayasa, infrastruktur, dan operasi.","body":["Kami membuka pembahasan dengan calon mitra di bidang energi, konektivitas, struktur dan manufaktur, komputasi, pengelolaan panas, sensor, serta operasi lapangan.","Kontribusi dapat dibahas berdasarkan kebutuhan pengembangan, batas antarmuka, tanggung jawab integrasi, serta hasil pengujian yang ingin dicapai bersama."],"cta":{"label":"Bahas Kontribusi Teknologi","formPreset":"industry"}},{"id":"research","h2":"Mengembangkan metode dan bukti yang dapat ditinjau.","body":["Perguruan tinggi dan lembaga riset dapat menjajaki kajian termal, struktur, keandalan, ekonomi, serta lingkungan. Ruang lingkup penelitian, penggunaan data, publikasi, dan hak atas hasil perlu disepakati sejak awal."],"cta":{"label":"Jajaki Kolaborasi Riset","formPreset":"research"}}],"process":{"h2":"Dari percakapan awal ke lingkup kerja bersama.","steps":["Sampaikan kebutuhan dan tujuan organisasi Anda.","Bahas kesesuaian serta informasi awal yang dapat dibagikan.","Rumuskan ruang lingkup, kontribusi, dan kriteria evaluasi.","Tentukan langkah berikutnya berdasarkan kesiapan kedua pihak."]},"contact":{"h2":"Ceritakan kebutuhan organisasi Anda.","body":"Sampaikan konteks singkat dan bentuk kerja sama yang ingin dijajaki. Jangan menyertakan informasi rahasia, kredensial, data operasional sensitif, atau dokumen terbatas dalam formulir ini.","privacyLink":"Pelajari pengelolaan data kontak Anda dalam Pemberitahuan Privasi.","helpText":"Tidak perlu menyertakan rincian teknis sensitif pada tahap awal.","fields":{"name":"Nama lengkap","org":"Nama organisasi","email":"Email yang dapat dihubungi","type":"Jenis kerja sama","selectPlaceholder":"Pilih jenis kerja sama","typeOptions":["Investor","Pemerintah atau institusi pertahanan","Mitra industri atau teknologi","Mitra riset","Lainnya"],"message":"Kebutuhan dan tujuan kerja sama","messagePlaceholder":"Jelaskan kebutuhan, kontribusi yang dapat ditawarkan, atau pertanyaan awal Anda.","submit":"Kirim Permintaan Diskusi"},"success":"Terima kasih. Permintaan diskusi Anda telah diterima. Tim Jalaranu akan meninjau informasi yang Anda kirimkan.","error":"Permintaan belum terkirim. Silakan coba lagi.","unavailable":"Formulir diskusi belum aktif. Tidak ada data yang dikirimkan dari halaman ini. Kanal kontak akan diumumkan setelah tersedia.","requiredError":"Lengkapi kolom ini.","emailError":"Masukkan alamat email yang valid.","captchaError":"Selesaikan pemeriksaan keamanan terlebih dahulu sebelum mengirim."}},"about":{"seoTitle":"Tentang Jalaranu | Identitas dan Pengembangan","seoDescription":"Kenali kisah di balik proyek datacenter bawah danau pertama di dunia: identitas Jalaranu, prinsip pengembangan, dan pihak yang bertanggung jawab.","hero":{"h1":"Berakar pada identitas Indonesia. Dibangun melalui pembuktian.","body":"Jalaranu mengembangkan datacenter bawah danau dan memandang danau Indonesia sebagai aset strategis nasional yang harus dipahami sebelum dimanfaatkan. Ambisi itu kami terjemahkan menjadi **proses yang terukur**: pertanyaan dan metode dipublikasikan di awal, dan temuan dibagikan bersama bukti serta batasannya begitu disetujui untuk dirilis. Pengembangan berjalan bertahap, dan kami menyatakan secara jujur apa yang sudah terbukti, apa yang belum terbukti, serta apa yang masih belum kami ketahui."},"story":{"h2":"Pengetahuan yang dijaga.","body":["Nama Jalaranu menggabungkan “jala”, yang dimaknai sebagai air dalam penamaan brand ini, dan “ranu”, danau. Identitasnya mengambil inspirasi visual dari warisan Jawa.","Sosok dewi penjaga menyangga bentuk datacenter di bawah gelombang air. Simbol ini menyampaikan tanggung jawab untuk menjaga pengetahuan dan infrastruktur yang menopangnya.","Makna tersebut diterjemahkan dalam cara proyek dikembangkan: pertanyaan yang jelas, pengujian yang terarah, dan komunikasi yang jujur tentang hasil serta keterbatasannya."]},"principles":{"h2":"Prinsip pengembangan","items":[{"title":"Bukti sebelum skala","body":"Keputusan pengembangan mengikuti hasil evaluasi."},{"title":"Tanggung jawab sepanjang umur fasilitas","body":"Perencanaan mencakup pemasangan, operasi, pemulihan, serta akhir masa pakai."},{"title":"Kolaborasi dengan peran yang jelas","body":"Kontribusi, antarmuka, dan tanggung jawab disepakati sejak awal."},{"title":"Keterbukaan yang proporsional","body":"Informasi publik menjelaskan dasar proyek; pembahasan terperinci mengikuti kebutuhan dan kewenangan akses."}]},"team":{"h2":"Tim dan organisasi","body":"Jalaranu dibangun oleh insan-insan yang berdedikasi dan percaya bahwa infrastruktur Indonesia harus dibangun di atas bukti terukur, bukan asumsi: para insinyur, praktisi keamanan, dan ahli strategi yang mempublikasikan pertanyaan dan metode proyek, serta berbagi temuan yang disetujui untuk dirilis. Pekerjaan ini ditata melalui tiga mitra dengan peran yang saling melengkapi: COCONUT Computer Club mengerjakan rekayasa, PERKAMINDO bertanggung jawab atas keamanan informasi, dan PT Lontar Riset Indonesia bertanggung jawab atas strategi dan bisnis. Kolaborasi tetap terbuka bagi pihak lain yang memiliki standar yang sama dengan proyek ini.","items":[{"name":"COCONUT Computer Club","role":"Rekayasa","url":"https://coconut.or.id","logo":"/assets/partners/coconut-logo-blue.svg"},{"name":"PERKAMINDO","role":"Keamanan informasi","url":"https://perkamindo.org","logo":"/assets/partners/perkamindo-horizontal.svg"},{"name":"PT Lontar Riset Indonesia","role":"Strategi dan bisnis","url":"https://lontartech.co.id","logo":"/assets/partners/lontar-logo.svg"}],"cta":{"label":"Terbuka untuk kolaborasi","to":"/id/partnerships/"}},"paper":{"h2":"Riset yang dipublikasikan","body":"Dasar rekayasa, model ancaman, penyaringan termal, dan perbandingan biaya di balik proyek ini terdokumentasi dalam paper terbuka. Baca langsung atau simpan salinannya.","linkLabel":"Paper - An Underlake Data Center Framework for Intelligence Infrastructure and Indonesian National Resilience","linkHref":"/assets/jalaranu-underlake-datacenter-paper.pdf","cite":"[PDF 1]"}},"privacy":{"seoTitle":"Privasi | Jalaranu","seoDescription":"Pemberitahuan Privasi Jalaranu akan menjelaskan pengelolaan data formulir kontak setelah praktiknya ditetapkan.","h1":"Pemberitahuan Privasi","body":["Pemberitahuan Privasi ini akan diperbarui sebelum formulir kontak diluncurkan. Halaman ini akan menjelaskan pengelola data, tujuan pemrosesan, penyedia layanan, retensi, serta kanal permintaan terkait data Anda setelah praktiknya ditetapkan."],"sections":[{"title":"Ruang lingkup pemberitahuan ini","body":["Halaman ini menjelaskan cara informasi kontak akan dikelola setelah formulir kontak Jalaranu dan proses terkaitnya aktif. Saat ini situs bersifat statis dan tidak mengumpulkan data pribadi dengan sendirinya."]},{"title":"Informasi yang direncanakan untuk dikumpulkan","body":["Ketika formulir kemitraan aktif, informasi yang diminta akan dibatasi pada hal yang diperlukan untuk meninjau permintaan: nama lengkap, nama organisasi, email yang dapat dihubungi, jenis kerja sama, dan pesan yang menjelaskan kebutuhan organisasi."]},{"title":"Cara informasi akan digunakan","body":["Informasi akan digunakan semata-mata untuk meninjau dan menanggapi permintaan kemitraan serta menyiapkan pembahasan lanjutan. Informasi tidak akan digunakan untuk pemasaran tanpa persetujuan dan tidak akan dijual kepada pihak ketiga."]},{"title":"Penyimpanan, retensi, dan akses","body":["Lokasi penyimpanan, masa retensi, kontrol akses, dan penanggung jawab data akan dipublikasikan di halaman ini setelah formulir dan praktik pemrosesannya ditetapkan. Sebelum itu, tidak ada data formulir yang diproses."]},{"title":"Hak Anda dan kontak","body":["Setelah pemrosesan dimulai, Anda dapat meminta informasi tentang data Anda, perbaikan, atau penghapusan melalui kanal kontak yang dipublikasikan di halaman ini. Gunakan formulir kontak pada halaman kemitraan untuk menghubungi tim terkait pemberitahuan ini."]}]},"notFound":{"h1":"Halaman tidak ditemukan","body":"Halaman yang Anda cari tidak tersedia atau telah dipindahkan.","back":"Kembali ke Beranda","seoTitle":"Halaman Tidak Ditemukan | Jalaranu","seoDescription":"Halaman yang Anda cari tidak dapat ditemukan. Kembali ke situs Jalaranu."}},"footer":{"privacy":"Privasi","contact":"Kontak","privacyNote":"Pemberitahuan Privasi akan diperbarui mengikuti praktik pengelolaan data yang berlaku.","legalHeading":"Hukum","email":"info@jalaranu.org"},"slugs":{"technology":"technology","useCases":"use-cases","validation":"milestones","partnerships":"partnerships","about":"about","privacy":"privacy"}}'),o=n(1396);const l={en:s,id:r},d=n.n(o)().siteMetadata.siteUrl,u=a=>"/id"===a||a.startsWith("/id/")?"id":"en",p=(a,e)=>{const n="en"===e?"id":"en";return a===`/${e}`||a.startsWith(`/${e}/`)?a.replace(`/${e}`,`/${n}`):`/${n}/`};function c(){const{0:a,1:e}=(0,i.useState)({locale:"en",currentPath:"/en/404/"});(0,i.useEffect)(()=>{const a=window.location.pathname,n=u(a);e({locale:n,currentPath:a})},[]);const n=l[a.locale],s={locale:a.locale,pageKey:"notFound",content:n,currentPath:a.currentPath,equivalentPath:p(a.currentPath,a.locale),siteUrl:d};return i.createElement(t.default,{pageContext:s})}function m({location:a}){const e=u(a.pathname),n=l[e].pages.notFound;return i.createElement(i.Fragment,null,i.createElement("html",{lang:e}),i.createElement("title",null,n.seoTitle),i.createElement("meta",{name:"description",content:n.seoDescription}),i.createElement("meta",{name:"robots",content:"noindex,follow"}))}}}]);
